mapper.select:
SELECT * FROM ${table.sqlName}

  AND directory_context_id=#{directoryContextId}
  AND owner_id=#{ownerId}
  AND parent_id=#{parentId}
  AND state=#{state}
 ORDER BY id DESC

SELECT * FROM pc_message WHERE owner_id=#{ownerId} AND session_id=#{sessionId}
  AND sequence_number > #{after} AND sequence_number <= #{end} AND state!='REVOKED_IMPORT'
  ORDER BY sequence_number,id LIMIT #{limit}

SELECT * FROM pc_event WHERE session_id=#{sessionId} AND parent_id=#{taskId}
  AND sequence_number > #{after} AND sequence_number <= #{end} AND state!='REVOKED_IMPORT'
  ORDER BY sequence_number,id LIMIT #{limit}

SELECT COUNT(*) FROM pc_task WHERE state IN ('LEASED','RUNNING','WAITING_APPROVAL','CANCELLING','RECONCILE_REQUIRED')
AND directory_context_id=#{directoryContextId}AND session_id=#{sessionId}
AND owner_id=#{ownerId}AND runner_id=#{runnerId}

SELECT r.* FROM pc_security_audit r WHERE r.directory_context_id=#{directoryContextId}
  AND r.owner_id=#{userId}

  AND REPLACE(r.payload,' ','') LIKE #{toolFilter} ESCAPE '!'
  AND REPLACE(r.payload,' ','') LIKE #{decisionFilter} ESCAPE '!'
  AND r.parent_id=#{taskId}
ORDER BY r.id DESC

SELECT r.* FROM pc_task r WHERE r.owner_id=#{userId} AND r.directory_context_id=#{directoryContextId}
  AND r.state=#{state}
  AND (r.task_title LIKE #{search} ESCAPE '!' OR r.prompt_text LIKE #{search} ESCAPE '!')
  AND EXISTS(SELECT 1 FROM sys_user u WHERE u.user_id=r.owner_id AND u.user_name LIKE #{requester} ESCAPE '!')
ORDER BY r.id DESC

SELECT r.* FROM pc_memory r WHERE r.kind NOT IN ('SCOPE_LOCK','PROJECT_RULE','POLICY') AND r.state NOT IN ('DELETED','REPLACED','REVOKED_IMPORT')
  AND r.directory_context_id IS NULL AND r.owner_id=#{userId}AND r.directory_context_id=#{directoryContextId}
    AND r.owner_id=#{userId}

  AND r.memory_content LIKE #{search} ESCAPE '!'
ORDER BY r.id DESC

SELECT r.* FROM ${table.sqlName} r WHERE
  r.owner_id=#{userId}
  AND r.directory_context_id=#{directoryContextId}
  AND r.owner_id=#{userId}
ORDER BY r.id DESC
